const caseName = pm.iterationData.get("caseName");
const maxCalories = Number(pm.iterationData.get("maxCalories"));
const mustBeVegetarian =
  String(pm.iterationData.get("mustBeVegetarian")).toLowerCase() === "true";
const excludedIngredient = String(
  pm.iterationData.get("excludedIngredient")
).toLowerCase();

pm.test(`${caseName}: status is 200`, function () {
  pm.response.to.have.status(200);
});

pm.test(`${caseName}: response contract is valid`, function () {
  const body = pm.response.json();

  pm.expect(body.pizza).to.be.an("object");
  pm.expect(body.pizza.name).to.be.a("string").and.not.empty;
  pm.expect(body.pizza.ingredients).to.be.an("array").and.not.empty;
  pm.expect(body.calories).to.be.a("number");
  pm.expect(body.vegetarian).to.be.a("boolean");

  for (const ingredient of body.pizza.ingredients) {
    pm.expect(ingredient.name).to.be.a("string").and.not.empty;
    pm.expect(ingredient.vegetarian).to.be.a("boolean");
  }
});

pm.test(`${caseName}: vegetarian restriction is respected`, function () {
  const body = pm.response.json();

  if (mustBeVegetarian) {
    pm.expect(body.vegetarian).to.equal(true);
    pm.expect(body.pizza.ingredients).to.be.an("array").and.not.empty;

    for (const ingredient of body.pizza.ingredients) {
      pm.expect(ingredient.vegetarian).to.equal(true);
    }
  }
});

pm.test(`${caseName}: excluded ingredient is absent`, function () {
  const body = pm.response.json();
  pm.expect(body.pizza.ingredients).to.be.an("array").and.not.empty;

  const names = body.pizza.ingredients.map(
    ingredient => ingredient.name.toLowerCase()
  );

  pm.expect(names).to.not.include(excludedIngredient);
});

pm.test(`${caseName}: calorie limit is respected`, function () {
  const body = pm.response.json();

  pm.expect(maxCalories).to.be.above(0);
  pm.expect(body.calories).to.be.a("number");
  pm.expect(body.calories).to.be.at.least(0);
  pm.expect(body.calories).to.be.at.most(maxCalories);
});
